  let currentModal = null;
  function load(){
    try{
      const raw=localStorage.getItem(STORAGE_KEY);
      if(!raw) return structuredClone(seed);
      const saved=JSON.parse(raw);
      // Migrate older/partial browser data without discarding existing user records.
      const merged={...structuredClone(seed),...saved};
      ['requests','quotations','projects','team','payments','invoices'].forEach(key=>{
        const defaults=Array.isArray(seed[key])?seed[key]:[];
        const existing=Array.isArray(saved[key])?saved[key]:[];
        const byId=new Map(defaults.map(item=>[item.id||item.name,item]));
        existing.forEach(item=>byId.set(item.id||item.name,{...(byId.get(item.id||item.name)||{}),...item}));
        merged[key]=[...byId.values()];
      });
      merged.managerProfile={...seed.managerProfile,...(saved.managerProfile||{})};
      return merged;
    }catch(e){console.warn('Dashboard data could not be loaded; using demo data.',e);return structuredClone(seed)}
  }
  function save(){localStorage.setItem(STORAGE_KEY,JSON.stringify(db));renderAll()}
  function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toastRegion').append(el);setTimeout(()=>el.remove(),3000)}
  function setPage(page){$$('.page-section').forEach(x=>x.classList.toggle('active',x.id==='page-'+page));$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$('#pageTitle').textContent=page[0].toUpperCase()+page.slice(1);$('#sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});renderPage(page)}
  function clientAvatar(name){const colors=['avatar-purple','avatar-coral','avatar-blue','avatar-green'];let n=[...String(name)].reduce((a,c)=>a+c.charCodeAt(0),0);return `<span class="avatar ${colors[n%4]}">${esc(initials(name))}</span>`}
  function findReq(id){return db.requests.find(x=>x.id===id)}
  function renderDashboard(){
    const activeReq=db.requests.filter(x=>['New','Under Review','Clarification'].includes(x.status)).length;
    const pendingQuotes=db.quotations.filter(x=>x.status==='Pending Approval').length;
    const activeProjects=db.projects.filter(x=>['In Progress','Planning','Client Review','On Hold'].includes(x.status)).length;
    const pendingPayments=db.payments.filter(x=>['Pending','Overdue'].includes(x.status)).length;
    $('#statRequests').textContent=activeReq;$('#statQuotes').textContent=pendingQuotes;$('#statProjects').textContent=activeProjects;$('#statPayments').textContent=pendingPayments;$('#requestNavCount').textContent=activeReq;
    const actions=[
      ...db.quotations.filter(x=>x.status==='Pending Approval').map(x=>({icon:'▤',purple:true,title:`${x.id} needs approval`,sub:`${x.client} · ${money(x.total)}`,action:'quotation',id:x.id,label:'Review'})),
      ...db.projects.filter(x=>x.status==='Client Review').map(x=>({icon:'◫',title:`${x.client} awaits review`,sub:`${x.id} · ${x.progress}% complete`,action:'project',id:x.id,label:'Review'})),
      ...db.requests.filter(x=>x.status==='New').slice(0,2).map(x=>({icon:'↗',title:`New request from ${x.client}`,sub:`${x.id} · ${x.service}`,action:'request',id:x.id,label:'Review'}))
    ].slice(0,6);
    $('#pendingCount').textContent=actions.length+' actions';
    $('#pendingActions').innerHTML=actions.length?actions.map(a=>`<div class="action-item"><div class="action-symbol ${a.purple?'purple-bg':''}">${a.icon}</div><div class="action-copy"><strong>${esc(a.title)}</strong><small>${esc(a.sub)}</small></div><button data-open="${a.action}" data-id="${a.id}">${a.label} →</button></div>`).join(''):'<div class="empty-state">You are all caught up.</div>';
    const deadlines=[
      ...db.quotations.filter(q=>['Sent','Pending Approval'].includes(q.status)).map(q=>({date:q.validUntil,title:`${q.id} · ${q.client}`,sub:'Quotation expiry',kind:'Quotation'})),
      ...db.projects.filter(p=>!['Completed'].includes(p.status)).map(p=>({date:p.due,title:`${p.id} · ${p.client}`,sub:'Project delivery',kind:'Project'})),
      ...db.payments.filter(p=>p.status!=='Paid').map(p=>({date:p.due,title:`${p.id} · ${p.client}`,sub:'Payment reminder',kind:'Payment'}))
    ].sort((a,b)=>a.date.localeCompare(b.date)).slice(0,5);
    $('#dashboardDeadlines').innerHTML=deadlines.map(d=>{const dt=new Date(d.date+'T00:00:00');const over=d.date<todayISO();return `<div class="deadline-item"><div class="deadline-date ${over?'overdue':''}"><b>${dt.getDate()}</b><small>${dt.toLocaleDateString('en-IN',{month:'short'}).toUpperCase()}</small></div><div class="deadline-copy"><strong>${esc(d.title)}</strong><small>${esc(d.sub)} · ${fmtDate(d.date)}</small></div><span class="deadline-tag">${over?'OVERDUE':esc(d.kind.toUpperCase())}</span></div>`}).join('')||'<div class="empty-state">No upcoming deadlines.</div>';
    $('#recentRequests').innerHTML=db.requests.slice(0,5).map(r=>`<tr><td><strong>${r.id}</strong></td><td><div class="client-cell">${clientAvatar(r.client)}<strong>${esc(r.client)}</strong></div></td><td>${esc(r.service)}</td><td>${status(r.status)}</td><td><button class="row-action" data-open="request" data-id="${r.id}">···</button></td></tr>`).join('');
    const avg=db.projects.length?Math.round(db.projects.reduce((a,p)=>a+p.progress,0)/db.projects.length):0;$('#overviewCompletion').textContent=avg+'%';$('#overviewProgress').style.width=avg+'%';$('#onTrackCount').textContent=db.projects.filter(p=>p.status==='In Progress'||p.status==='Completed').length;$('#atRiskCount').textContent=db.projects.filter(p=>p.status==='On Hold'||(p.due<todayISO()&&p.status!=='Completed')).length;
  }
  function renderRequests(){
    const q=($('#requestSearch')?.value||'').toLowerCase(),st=$('#requestStatusFilter')?.value||'all',sv=$('#requestServiceFilter')?.value||'all';
    const rows=db.requests.filter(r=>(st==='all'||r.status===st)&&(sv==='all'||r.service===sv)&&[r.id,r.client,r.service,r.description].join(' ').toLowerCase().includes(q));
    $('#requestsTable').innerHTML=rows.map(r=>`<tr><td><strong>${r.id}</strong></td><td><div class="client-cell">${clientAvatar(r.client)}<strong>${esc(r.client)}</strong></div></td><td>${esc(r.service)}</td><td>${fmtDate(r.submitted)}</td><td>${esc(r.timeline)}</td><td>${status(r.status)}</td><td><button class="inline-link" data-open="request" data-id="${r.id}">Review →</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty-state">No requests match your filters.</td></tr>';
  }
  function renderQuotes(){
    const q=($('#quoteSearch')?.value||'').toLowerCase(),st=$('#quoteStatusFilter')?.value||'all';
    const rows=db.quotations.filter(x=>(st==='all'||x.status===st)&&[x.id,x.client,x.service,x.requestId].join(' ').toLowerCase().includes(q));
    $('#quotationsTable').innerHTML=rows.map(x=>`<tr><td><strong>${x.id}</strong></td><td><strong>${esc(x.client)}</strong><br><small class="muted">${esc(x.requestId||'—')}</small></td><td>${esc(x.service)}</td><td><strong>${money(x.total)}</strong></td><td>${fmtDate(x.validUntil)}</td><td>${status(x.status)}</td><td><button class="inline-link" data-open="quotation" data-id="${x.id}">Open →</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty-state">No quotations match your filters.</td></tr>';
    $('#quoteTotal').textContent=db.quotations.length;$('#quoteAwaiting').textContent=db.quotations.filter(x=>x.status==='Pending Approval').length;$('#quoteSent').textContent=db.quotations.filter(x=>x.status==='Sent').length;$('#quoteValue').textContent=money(db.quotations.filter(x=>x.status==='Accepted').reduce((a,x)=>a+x.total,0));
  }
  function renderProjects(){
    const q=($('#projectSearch')?.value||'').trim().toLowerCase(),st=$('#projectStatusFilter')?.value||'all';
    const rows=db.projects.filter(p=>(st==='all'||p.status===st)&&[p.id,p.client,p.service,p.lead].join(' ').toLowerCase().includes(q));
    const count=$('#projectCount'); if(count) count.textContent=`Showing ${rows.length} of ${db.projects.length} projects`;
    $('#projectGrid').innerHTML=rows.map(p=>`<article class="project-card"><div class="project-card-top"><div><h3>${esc(p.client)}</h3><p>${esc(p.id)} · ${esc(p.service)}</p></div>${status(p.status)}</div><div class="project-meta"><span>◷ Due ${fmtDate(p.due)}</span><span>♙ ${esc(p.lead||'Unassigned')}</span></div><div class="project-progress"><span>Project progress</span><b>${Number(p.progress)||0}%</b></div><div class="progress-track"><span style="width:${Math.max(0,Math.min(100,Number(p.progress)||0))}%"></span></div><div class="project-card-footer"><span class="muted">${(p.milestones||[]).filter(m=>m.done).length}/${(p.milestones||[]).length} milestones complete</span><button type="button" class="inline-link" data-open="project" data-id="${esc(p.id)}">Manage project →</button></div></article>`).join('')||'<div class="panel empty-state">No projects match your filters. <button type="button" class="inline-link" data-action="clear-project-filters">Show all projects</button></div>';
  }
  function renderTeam(){
    const leads=db.team.filter(t=>t.role==='Team Lead'),devs=db.team.filter(t=>t.role==='Developer'),active=db.projects.filter(p=>p.status!=='Completed');
    $('#teamSummary').innerHTML=`<div><span>Team members</span><strong>${db.team.length}</strong></div><div><span>Team leads</span><strong>${leads.length}</strong></div><div><span>Active allocations</span><strong>${active.length}</strong></div>`;
    $('#teamGrid').innerHTML=db.team.map(t=>{const assigned=active.filter(p=>p.lead===t.name||p.developers.includes(t.name)).length;return `<article class="team-card"><div class="team-card-head">${clientAvatar(t.name)}<div><h3>${esc(t.name)}</h3><p>${esc(t.role)}</p></div><span class="availability ${t.availability==='Busy'?'busy':''}">${t.availability}</span></div><div class="workload-row"><div><span>Current workload</span><b>${t.capacity}%</b></div><div class="progress-track"><span style="width:${t.capacity}%;background:${t.capacity>85?'var(--accent)':'var(--primary)'}"></span></div></div><div class="team-card-head" style="margin-top:12px"><p>${assigned} active project allocation${assigned===1?'':'s'}</p></div><div class="team-skills">${t.skills.map(s=>`<span class="skill">${esc(s)}</span>`).join('')}</div></article>`}).join('');
    $('#allocationTable').innerHTML=active.map(p=>{const lead=db.team.find(t=>t.name===p.lead);return `<tr><td><strong>${p.id}</strong><br><small class="muted">${esc(p.client)}</small></td><td>${esc(p.lead||'Unassigned')}</td><td>${p.developers.map(esc).join(', ')||'—'}</td><td>${lead?lead.capacity+'%':'—'}</td><td>${status(p.status)}</td><td><button class="inline-link" data-open="assignment" data-id="${p.id}">Reassign →</button></td></tr>`}).join('');
  }
  function renderClients(){
    const q=($('#clientSearch')?.value||'').toLowerCase();
    const names=[...new Set([...db.requests.map(x=>x.client),...db.projects.map(x=>x.client),...db.payments.map(x=>x.client)])].filter(n=>n.toLowerCase().includes(q));
    $('#clientGrid').innerHTML=names.map(n=>{const req=db.requests.filter(x=>x.client===n),pr=db.projects.filter(x=>x.client===n);return `<article class="client-card"><div class="client-card-head">${clientAvatar(n)}<div><h3>${esc(n)}</h3><p>${esc(req[0]?.email||'Client account')}</p></div><span class="status ${pr.length?'in-progress':'new'}">${pr.length?'Active client':'Prospect'}</span></div><div class="client-stats"><div><span>Requests</span><b>${req.length}</b></div><div><span>Projects</span><b>${pr.length}</b></div><div><span>Open items</span><b>${db.payments.filter(x=>x.client===n&&x.status!=='Paid').length}</b></div></div><div style="margin-top:12px"><button class="inline-link" data-client="${esc(n)}">View history →</button></div></article>`}).join('')||'<div class="panel empty-state">No clients found.</div>';
  }
  function renderPayments(){$('#paymentsTable').innerHTML=db.payments.map(p=>`<tr><td><strong>${p.id}</strong></td><td>${esc(p.client)}</td><td>${esc(p.project)}</td><td><strong>${money(p.amount)}</strong></td><td>${fmtDate(p.due)}</td><td>${status(p.status)}</td></tr>`).join('');$('#paymentPendingCount').textContent=db.payments.filter(p=>p.status!=='Paid').length}
  function renderInvoices(){$('#invoicesTable').innerHTML=db.invoices.map(i=>`<tr><td><strong>${i.id}</strong></td><td>${esc(i.client)}</td><td>${esc(i.project)}</td><td>${fmtDate(i.issued)}</td><td>${fmtDate(i.due)}</td><td><strong>${money(i.amount)}</strong></td><td>${status(i.status)}</td></tr>`).join('')}
  function renderReports(){
    const total=db.requests.length,accepted=db.requests.filter(x=>x.status==='Accepted').length,done=db.projects.filter(x=>x.status==='Completed').length,overdue=db.projects.filter(x=>x.due<todayISO()&&x.status!=='Completed').length,avg=db.projects.length?Math.round(db.projects.reduce((a,p)=>a+p.progress,0)/db.projects.length):0;
    $('#reportMetrics').innerHTML=[['Request conversion',`${total?Math.round(accepted/total*100):0}%`,'Accepted requests'],['Quotation acceptance',`${db.quotations.length?Math.round(db.quotations.filter(x=>x.status==='Accepted').length/db.quotations.length*100):0}%`,'Accepted quotations'],['Avg. project progress',avg+'%','Across active and completed'],['Overdue projects',overdue,'Require attention'],['Completed projects',done,'Delivered'],['Team members',db.team.length,'Across delivery roles']].map(x=>`<div class="report-metric"><span>${x[0]}</span><strong>${x[1]}</strong><small>${x[2]}</small></div>`).join('');
    const leads=db.team.filter(t=>t.role==='Team Lead');$('#workloadReport').innerHTML=leads.map(t=>`<div class="bar-row"><span>${esc(t.name)}</span><div class="progress-track"><span style="width:${t.capacity}%;background:${t.capacity>85?'var(--accent)':'var(--primary)'}"></span></div><b>${t.capacity}%</b></div>`).join('')||'<p class="empty-state">No team leads found.</p>';
    const states=['New','Under Review','Clarification','Accepted','Rejected'];const max=Math.max(1,...states.map(s=>db.requests.filter(r=>r.status===s).length));$('#conversionReport').innerHTML=`<div class="conversion-bars">${states.map(s=>{const n=db.requests.filter(r=>r.status===s).length;return `<div class="conversion-item"><i style="height:${n/max*78}%"></i><b>${n}</b><span>${s}</span></div>`}).join('')}</div>`;
  }
